// Combine all data for application
const jobData = $('🔀 Merge Resume Paths').first().json;
const coverLetterResponse = $input.first().json;
const coverLetter = coverLetterResponse.choices[0].message.content;

// Use the apply_type from the fetched job page (more accurate than search result)
const isEasyApply = (jobData.apply_type || '').includes('Easy Apply');

return [{
  json: {
    ...jobData,
    cover_letter: coverLetter,
    is_easy_apply: isEasyApply,
    ready_to_apply: true,
    application_timestamp: new Date().toISOString()
  }
}];

// Set status for successfully submitted Easy Apply
const job = $('📋 Prepare Application Data').first().json;
const apifyResult = $input.first().json;

return [{
  json: {
    ...job,
    new_status: 'Applied',
    application_id: apifyResult.id || apifyResult.data?.id || 'auto_applied',
    applied_date: new Date().toISOString().split('T')[0],
    notes: `Easy Apply submitted via Apify. Cover letter generated. Skill match: ${job.skill_match_score}%`,
    cover_letter_generated: 'Yes',
    resume_optimized: job.resume_was_updated ? 'Yes' : 'No'
  }
}];

// Set status for jobs requiring manual/direct application
const job = $('📋 Prepare Application Data').first().json;

return [{
  json: {
    ...job,
    new_status: 'Manual Apply Required',
    application_id: '',
    applied_date: '',
    notes: `External apply needed. Cover letter ready. Apply at: ${job.job_url}. Skill match: ${job.skill_match_score}%. Missing skills: ${job.missing_skills}`,
    cover_letter_generated: 'Yes',
    resume_optimized: job.resume_was_updated ? 'Yes' : 'No'
  }
}];

// Generate a status report of all applied jobs
const jobs = $input.all();

const byStatus = {};
for (const item of jobs) {
  const status = item.json.status || 'Unknown';
  if (!byStatus[status]) byStatus[status] = [];
  byStatus[status].push(item.json);
}

const totalApplied = jobs.length;
const needsFollowUp = jobs.filter(j => {
  const appliedDate = new Date(j.json.applied_date || 0);
  const daysSince = (Date.now() - appliedDate.getTime()) / (1000 * 60 * 60 * 24);
  return daysSince >= 7 && j.json.status === 'Applied';
});

return [{
  json: {
    total_applied: totalApplied,
    needs_followup_count: needsFollowUp.length,
    needs_followup: needsFollowUp.map(j => j.json),
    all_jobs: jobs.map(j => j.json),
    report_date: new Date().toISOString().split('T')[0],
    summary_by_status: byStatus
  }
}];

// Sync applied_date when you change status in Google Sheets
const staticData = $getWorkflowStaticData('global');
if (!staticData.jobStatusSnapshot) staticData.jobStatusSnapshot = {};

const today = new Date().toLocaleDateString('en-CA', { timeZone: 'Europe/Berlin' }); // YYYY-MM-DD in local tz

function norm(s) {
  return String(s || '').trim().toLowerCase();
}

function isAppliedLike(status) {
  const n = norm(status);
  if (!n) return false;
  const notApplied = ['not applied', 'new', 'to apply', 'not applied yet', 'open', 'saved'];
  if (notApplied.includes(n)) return false;
  const appliedTerms = [
    'applied', 'application sent', 'submitted', 'interview', 'interviewing',
    'offer', 'rejected', 'withdrawn', 'in progress', 'screening', 'phone screen',
    'assessment', 'hired', 'accepted'
  ];
  return appliedTerms.some(t => n === t || n.includes(t));
}

const updates = [];
const rows = $input.all();

for (const item of rows) {
  const j = item.json;
  const jobId = String(j.job_id || j.Job_ID || j['job id'] || '').trim();
  if (jobId.length < 3) continue;

  const status = String(j.status || j.Status || 'Not Applied').trim();
  const appliedDate = String(
    j.applied_date || j['applied date'] || j.Applied_Date || j['Applied Date'] || ''
  ).trim();

  const prev = staticData.jobStatusSnapshot[jobId] || null;
  const prevStatus = prev ? String(prev.status || '').trim() : '';

  let newAppliedDate = null;

  if (isAppliedLike(status)) {
    if (!appliedDate) {
      // Applied in sheet, date missing → fill today
      newAppliedDate = today;
    } else if (prevStatus && norm(prevStatus) !== norm(status) && !isAppliedLike(prevStatus)) {
      // Just changed to Applied (or similar)
      newAppliedDate = today;
    }
  }

  staticData.jobStatusSnapshot[jobId] = {
    status,
    applied_date: newAppliedDate || appliedDate || (prev?.applied_date || ''),
  };

  if (newAppliedDate) {
    updates.push({
      json: {
        job_id: jobId,
        row_number: j.row_number,
        status,
        applied_date: newAppliedDate,
        last_checked: today,
      }
    });
  }
}

console.log(`Status sync: ${rows.length} rows checked → ${updates.length} applied_date update(s)`);
if (updates.length === 0) return [{ json: { _noUpdates: true } }];
return updates;

// Build Apify LinkedIn Job Scraper input from Config
const cfg = $('⚙️ Config').first().json;
const queries = String(cfg.searchQueries || 'Product Manager')
  .split(',').map(q => q.trim()).filter(Boolean);
const experienceLevel = String(cfg.apifyExperienceLevels || 'entry-level,associate,mid-senior').split(',').map(s => s.trim()).filter(Boolean);
return [{
  json: {
    keyword:    queries,
    locations:  [String(cfg.searchLocation || 'Germany')],
    publishedAt:'r604800',
    jobType:    ['full-time'],
    maxItems:   200,
    saveOnlyUniqueItems: true,
    experienceLevel
  }
}];

// Transform Apify cheap_scraper/linkedin-job-scraper output
// to same shape as '📋 Parse LinkedIn HTML → Job Data'
const cfg = $('⚙️ Config').first().json;
const ENGLISH_ONLY = cfg.englishOnly !== 'false' && cfg.englishOnly !== false;

const ROLE_TERMS = String(cfg.searchQueries || '')
  .split(',').map(k => k.trim().toLowerCase()).filter(Boolean);
const EXCLUDED_KW = String(cfg.excludedRoleKeywords || '')
  .split(',').map(k => k.trim().toLowerCase()).filter(Boolean);

function isEnglish(title) {
  if (!ENGLISH_ONLY) return true;
  const t = (title || '').toLowerCase();
  if (/\([mwfd]*w[mwfd]*\/[mwfd]+\/[dxm]\)/i.test(t)) return false;
  if (/[äöüß]/i.test(title || '')) return false;
  const de = [' für ',' und ',' mit ',' als ',' von ',' zur ',' zum ',
    ' der ',' die ',' das ',' im ',' zu ','entwickler','leiter','berater',
    'mitarbeiter','projektleiter','kaufmann','kauffrau','fachkraft',
    'werkstudent','referent','fachinformatiker','vollzeit','teilzeit','praktikum'];
  return !de.some(w => t.includes(w));
}
function isExcluded(title) {
  const t = (title||'').toLowerCase();
  return EXCLUDED_KW.some(kw => t.includes(kw));
}
function matchesRole(title) {
  if (ROLE_TERMS.length === 0) return true;
  const t = (title||'').toLowerCase();
  return ROLE_TERMS.some(term => t.includes(term));
}

const raw = $input.all();
const jobs = [];
for (const item of raw) {
  const j = item.json;
  const title = j.jobTitle || '';
  if (!isEnglish(title)) continue;
  if (isExcluded(title)) continue;
  if (!matchesRole(title)) continue;
  const jobId = String(j.jobId || '').trim();
  if (!jobId) continue;
  jobs.push({
    json: {
      job_id:     'li_' + jobId,
      company:    j.companyName || 'Unknown',
      position:   title,
      location:   j.location || 'Unknown',
      job_url:    j.jobUrl || ('https://www.linkedin.com/jobs/view/' + jobId + '/'),
      apply_type: j.applyType === 'EASY' ? 'LinkedIn Easy Apply' : 'LinkedIn External',
      is_linkedin: 'Yes',
      is_remote:   (j.workType||'').toLowerCase().includes('remote') ? 'Yes' : 'No',
      employment_type: 'FULLTIME',
      posted_date:     j.publishedAt ? j.publishedAt.split('T')[0] : new Date().toISOString().split('T')[0],
      description:     '',
      status:          'Not Applied',
      priority:        'Medium',
      applied_date:    '',
      cover_letter_generated: 'No',
      resume_optimized:       'No',
      missing_skills:  '',
      application_id:  '',
      notes:           j.applicationsCount || '',
      fetched_date:    new Date().toISOString().split('T')[0],
      last_checked:    new Date().toISOString().split('T')[0],
      hasNewJobs:      false,
      _source:         'apify'
    }
  });
}
