const incomingJobs = $('📋 Parse Apify Jobs').all();
const sheetRows    = $('📊 Get Existing IDs [Apify]').all();
const cfg = $('⚙️ Config').first().json;

const ENGLISH_ONLY = cfg.englishOnly !== 'false' && cfg.englishOnly !== false;
const ROLE_TERMS = String(cfg.searchQueries || '')
  .split(',').map(k => k.trim().toLowerCase()).filter(Boolean);
const EXCLUDED_KW = String(cfg.excludedRoleKeywords || '')
  .split(',').map(k => k.trim().toLowerCase()).filter(Boolean);

function isEnglish(title) {
  if (!ENGLISH_ONLY) return true;
  const t = (title||'').toLowerCase();
  if (/\([mwfd]*w[mwfd]*\/[mwfd]+\/[dxm]\)/i.test(t)) return false;
  if (/[äöüß]/i.test(title||'')) return false;
  const de = [' für ',' und ',' mit ',' als ',' von ',' zur ',' zum ',
    ' der ',' die ',' das ',' im ',' zu ','entwickler','leiter','berater',
    'mitarbeiter','projektleiter','kaufmann','kauffrau','fachkraft',
    'werkstudent','referent','fachinformatiker','vollzeit','teilzeit','praktikum'];
  return !de.some(w => t.includes(w));
}
function isExcluded(t) { const s=(t||'').toLowerCase(); return EXCLUDED_KW.some(k=>s.includes(k)); }
function matchesRole(t) { if(!ROLE_TERMS.length) return true; const s=(t||'').toLowerCase(); return ROLE_TERMS.some(k=>s.includes(k)); }
function normaliseKey(c,t) {
  const clean = s => (s||'').toLowerCase().replace(/\(.*?\)/g,'').replace(/[^a-z0-9 ]/g,' ').replace(/\s+/g,' ').trim();
  return `${clean(c)}|${clean(t)}`;
}

const existingIds  = new Set(sheetRows.map(r => String(r.json.job_id||'').trim()).filter(Boolean));
const existingKeys = new Set(sheetRows.map(r => normaliseKey(r.json.company||'', r.json.position||r.json.title||'')).filter(s=>s.length>5));

const seenInRun = new Set();
let langSkip=0, exclSkip=0, roleSkip=0, dupSkip=0;

const newJobs = incomingJobs.filter(item => {
  const j = item.json;
  if (j._empty) return false;
  const title = j.position || '';
  if (!isEnglish(title))   { langSkip++;  return false; }
  if (isExcluded(title))   { exclSkip++;  return false; }
  if (!matchesRole(title)) { roleSkip++;  return false; }
  const jobId = String(j.job_id||'').trim();
  if (!jobId || seenInRun.has(jobId)) return false;
  seenInRun.add(jobId);
  if (existingIds.has(jobId)) { dupSkip++; return false; }
  const key = normaliseKey(j.company||'', title);
  if (existingKeys.has(key)) { dupSkip++; return false; }
  return true;
});

console.log(`Apify filter: ${incomingJobs.length} → lang:${langSkip} excl:${exclSkip} role:${roleSkip} dup:${dupSkip} → ${newJobs.length} new`);
if (newJobs.length === 0) return [{ json: { _noNew: true } }];
return newJobs.map(j => ({ json: { ...j.json, _noNew: false } }));

